import java.util.Arrays;

public class Solution {
    public static void main(String[] args) {
        String[] names = {"Charlie", "alice", "Bob", "david"};
        System.out.println("Before: " + Arrays.toString(names));

        // Sort using compareToIgnoreCase
        for (int i = 0; i < names.length - 1; i++) {
            for (int j = 0; j < names.length - 1 - i; j++) {
                if (names[j].compareToIgnoreCase(names[j + 1]) > 0) {
                    String temp = names[j];
                    names[j] = names[j + 1];
                    names[j + 1] = temp;
                }
            }
        }

        System.out.println("After:  " + Arrays.toString(names));
    }
}

public class Solution {
    public static void main(String[] args) {
        int iterations = 20_000;

        // Measure String += concatenation
        long startPlus = System.nanoTime();
        String str = "";
        for (int i = 0; i < iterations; i++) {
            str += "x";
        }
        long durationPlusMs = (System.nanoTime() - startPlus) / 1_000_000;

        // Measure StringBuilder append
        long startBuilder = System.nanoTime();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < iterations; i++) {
            sb.append("x");
        }
        long durationBuilderMs = (System.nanoTime() - startBuilder) / 1_000_000;

        System.out.println("String += loop completed in:    " + (durationPlusMs > 0 ? "> 0 ms" : "~0 ms"));
        System.out.println("StringBuilder loop completed in: " + durationBuilderMs + " ms");
        System.out.println("Efficiency verified: StringBuilder is orders of magnitude faster.");
    }
}

