}

public class Solution {
    public static int compareVersions(String v1, String v2) {
        String[] parts1 = v1.split("\\.");
        String[] parts2 = v2.split("\\.");
        int maxLen = Math.max(parts1.length, parts2.length);

        for (int i = 0; i < maxLen; i++) {
            int n1 = i < parts1.length ? Integer.parseInt(parts1[i]) : 0;
            int n2 = i < parts2.length ? Integer.parseInt(parts2[i]) : 0;
            if (n1 != n2) {
                return Integer.compare(n1, n2);
            }
        }
        return 0;
    }

    public static void main(String[] args) {
        String vA = "1.2";
        String vB = "1.10";
        int cmp = compareVersions(vA, vB);
        System.out.println("Comparing '" + vA + "' vs '" + vB + "': " + (cmp < 0 ? "vB is newer" : "vA is newer"));

        String vC = "1.01";
        String vD = "1.001";
        System.out.println("Comparing '" + vC + "' vs '" + vD + "': " + (compareVersions(vC, vD) == 0 ? "Versions are equal" : "Versions differ"));
    }
}

