}

public class Solution {
    public static int manualHashCode(String s) {
        int h = 0;
        for (int i = 0; i < s.length(); i++) {
            h = 31 * h + s.charAt(i);
        }
        return h;
    }

    public static void main(String[] args) {
        String s1 = "Aa";
        String s2 = "BB";

        System.out.println("Manual hash for 'Aa':   " + manualHashCode(s1));
        System.out.println("Library hashCode('Aa'): " + s1.hashCode());
        System.out.println("Library hashCode('BB'): " + s2.hashCode());
        System.out.println("Hash collision verified: " + (s1.hashCode() == s2.hashCode()));
    }
}

import java.util.Arrays;

public class Solution {
    public static int lengthOfLongestSubstring(String s) {
        int[] lastIndex = new int[256];
        Arrays.fill(lastIndex, -1);
        int maxLen = 0;
        int left = 0;

        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);
            if (lastIndex[ch] >= left) {
                left = lastIndex[ch] + 1;
            }
            lastIndex[ch] = right;
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }

    public static void main(String[] args) {
        String text = "abcabcbb";
        System.out.println("Input: " + text);
        System.out.println("Longest unique substring length: " + lengthOfLongestSubstring(text));
    }
}

public class Solution {
    public static String longestPalindrome(String s) {
        if (s == null || s.length() < 2) return s;
        int start = 0, maxLen = 0;

        for (int i = 0; i < s.length(); i++) {
            int len1 = expandAroundCenter(s, i, i);     // Odd-length center
            int len2 = expandAroundCenter(s, i, i + 1); // Even-length center
            int len = Math.max(len1, len2);
            if (len > maxLen) {
                maxLen = len;
                start = i - (len - 1) / 2;
            }
        }
        return s.substring(start, start + maxLen);
    }

    private static int expandAroundCenter(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        return right - left - 1;
    }

    public static void main(String[] args) {
        String text = "babad";
        System.out.println("Input: " + text);
        System.out.println("Longest Palindromic Substring: " + longestPalindrome(text));
    }
}

