public class Solution {
    public static String minWindow(String s, String t) {
        if (s.length() < t.length()) return "";
        int[] targetCounts = new int[128];
        for (char c : t.toCharArray()) targetCounts[c]++;

        int required = 0;
        for (int count : targetCounts) if (count > 0) required++;

        int[] windowCounts = new int[128];
        int formed = 0;
        int left = 0, right = 0;
        int minLen = Integer.MAX_VALUE;
        int minStart = 0;

        while (right < s.length()) {
            char c = s.charAt(right);
            windowCounts[c]++;
            if (targetCounts[c] > 0 && windowCounts[c] == targetCounts[c]) {
                formed++;
            }
            while (left <= right && formed == required) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minStart = left;
                }
                char leftChar = s.charAt(left);
                windowCounts[leftChar]--;
                if (targetCounts[leftChar] > 0 && windowCounts[leftChar] < targetCounts[leftChar]) {
                    formed--;
                }
                left++;
            }
            right++;
        }
        return minLen == Integer.MAX_VALUE ? "" : s.substring(minStart, minStart + minLen);
    }

    public static void main(String[] args) {
        String s = "ADOBECODEBANC";
        String t = "ABC";
        String window = minWindow(s, t);
        System.out.println("Source: " + s + " | Target: " + t);
        System.out.println("Minimum Window Substring: " + window);
    }
}

public class Solution {
    public static boolean isMatch(String s, String p) {
        int sIdx = 0, pIdx = 0;
        int matchIdx = 0, starIdx = -1;

        while (sIdx < s.length()) {
            if (pIdx < p.length() && (p.charAt(pIdx) == '?' || p.charAt(pIdx) == s.charAt(sIdx))) {
                sIdx++;
                pIdx++;
            } else if (pIdx < p.length() && p.charAt(pIdx) == '*') {
                starIdx = pIdx;
                matchIdx = sIdx;
                pIdx++;
            } else if (starIdx != -1) {
                pIdx = starIdx + 1;
                matchIdx++;
                sIdx = matchIdx;
            } else {
                return false;
            }
        }

        while (pIdx < p.length() && p.charAt(pIdx) == '*') {
            pIdx++;
        }
        return pIdx == p.length();
    }

    public static void main(String[] args) {
        String text = "abcdef";
        String pattern = "a?c*f";
        System.out.println("Matching '" + text + "' against pattern '" + pattern + "':");
        System.out.println("Result: " + isMatch(text, pattern));
    }
}
